/* Screens composed from the APK's original UI sprites. Values come from game state. */
(()=>{
'use strict';
const art={body:'ae487349e50523247a9bd6945f638c8e_2',close:'7fce1b55a004a5d4da54d0de239b0f2a_2',yellow:'1a2d3e7dc1dbacb46b77f62100c5477a_2',green:'bd6a8ad4b068d0846ba2dcf60841fb34_2',red:'c6ca3c90e2ff9bf44958ecd9aaf760e5_2',blue:'cb6b27e485a6d0440853d87e85501dd1_2',frame:'0c8c5b028d3f86f4b962f8096732f7fb_2',compass:'4d3764bbfe63b654f8c3134d397bd0a1_2',lock:'f6f584584745554488e2baa66f0c421b_2',paper:'07cf5c66ca4802f45b38211ec4bcd2c7_2',medal:'04f378a587f28364fb31fa36f8b052cb_2'};
const button=(c,label,action,color='yellow',extra='')=>`<button class="ref-button ${color}" style="--button-image:url('${c.assetSrc(art[color])}')" data-action="${action}" ${extra}>${label}</button>`;
const stars=(c,count,cls='')=>`<span class="ref-item-stars ${cls}">${Array.from({length:Math.min(6,count||1)},()=>c.img(c.named('hero_star_1'))).join('')}</span>`;
function tile(c,item,quantity=null,action='item'){
 // Bảo vật: khung ItemArtifactUI gốc (nền/viền theo phẩm, cột sao, lấp lánh bảo vật đỏ).
 if(item.category==='artifact'&&window.ArtifactUI&&c.catalog?.artifactUpgrade)return `<button class="ref-item item-cell artifact-tile" data-action="${action}" data-item="${c.escape(item.id)}" aria-label="${c.escape(item.name)}" title="${c.escape(item.name)}">${window.ArtifactUI.cell(item,{qty:quantity})}</button>`;
 return `<button class="ref-item item-cell" data-action="${action}" data-item="${c.escape(item.id)}" aria-label="${c.escape(item.name)}" title="${c.escape(item.name)}"><span class="ref-item-background ${item.category}"></span>${c.img(item.assetKey,'ref-item-art',item.name).replace('<img ','<img loading="lazy" ')}${c.img(art.frame,'ref-item-frame')}${window.ItemDecor?.sparkle(item)||''}${item.points||item.heroShard?window.ItemDecor?.stars(item)||'':item.category==='equipment'||item.category==='artifact'?stars(c,item.stars):''}${quantity!==null?`<span class="ref-item-quantity">${c.short(quantity)}</span>`:''}</button>`;
}
function overlay(c,title,content,type){return `<div class="reference-shade"><section class="reference-window ${type}" role="dialog" aria-modal="true" aria-label="${title}" style="--panel-image:url('${c.assetSrc(art.body)}')"><h2 class="reference-title">${title}</h2><button class="reference-close" data-action="close" aria-label="Đóng">${c.img(art.close)}</button>${content}</section></div>`}
function equipment(c){
 const positions={helmet:[210,90],armor:[65,165],pants:[355,165],boots:[210,360],accessory:[355,295]};
 return `<section class="reference-equipment"><h2 class="ref-section-title" style="background-image:url('${c.assetSrc(c.named('tag_title'))}')">Trang bị</h2>${c.img(art.compass,'equipment-compass')}<div class="equipment-grid">${Object.entries(positions).map(([slot,[x,y]])=>{const item=c.itemMap.get(c.player.hero.equipment[slot]);return `<div class="reference-gear" style="left:${x}px;top:${y}px" title="${c.slotNames[slot]}">${item?tile(c,item):`<button class="empty-gear" data-action="gear-pick" data-slot="${slot}" aria-label="Chọn ${c.slotNames[slot]}">${c.img(c.named(({helmet:'slot_helmet',armor:'slot_armor',pants:'slot_pants',boots:'slot_boots',accessory:'slot_artifact'})[slot])||c.named('icon_gear'))}</button>`}</div>`}).join('')}<div class="reference-gear" style="left:65px;top:295px" title="Đá hộ mệnh">${window.stoneSlotHtml()}</div></div><div class="equipment-actions">${button(c,'Trang bị nhanh','equip-best','green','data-submit')}${button(c,'Gỡ trang bị','unequip-all','yellow','data-submit')}</div><button class="equipment-bag-link" data-action="inventory">Mở túi đồ</button></section>`;
}
// Số gọn cho hàng nguyên liệu Thức tỉnh: 1.5K / 2.3M / 4B / 1T (bỏ .0).
const compact=n=>{n=Number(n)||0;for(const [v,u,d] of [[1e12,'T',1e12],[1e9,'B',1e9],[1e6,'M',1e6],[1e4,'K',1e3]])if(n>=v)return (n/d).toFixed(n/d>=100?0:1).replace(/\.0$/,'')+u;return String(Math.round(n))};
function awakening(c){
 const h=c.player.hero,cost=c.player.costs.star,max=h.stars>=c.catalog.economy.maxStars,next=Math.min(c.catalog.economy.maxStars,h.stars+1),cap=cost.nextCap;
 const materials=Object.entries(cost.items).map(([id,need])=>{const item=c.itemMap.get(id),owned=c.player.inventory[id]||0;return `<div><span>${c.escape(item?.name||id)}</span>${item?tile(c,item,null,'star-material'):''}<strong class="${owned>=need?'enough':'missing'}">${compact(owned)}/${compact(need)}</strong></div>`}).join('');
 return `<section class="reference-awakening"><div class="awakening-preview"><p>Tăng lực chiến: <strong class="enough">20%</strong></p><p>Cấp độ tối đa ${max?c.player.costs.level.maxLevel:cap}</p><div class="awakening-stars">${window.heroStarsHtml(h.stars)}${max?'':`<b>»</b>${window.heroStarsHtml(next)}`}</div></div><h2>Nguyên liệu</h2><div class="awakening-materials">${materials}<div><span>Vàng</span><div class="ref-material-icon">${c.img(c.named('icon_gold'))}${c.img(art.frame,'ref-item-frame')}</div><strong class="${c.player.wallet.gold>=cost.gold?'enough':'missing'}">${compact(c.player.wallet.gold)}/${compact(cost.gold)}</strong></div><div><span>Cấp tướng</span><div class="ref-material-icon">${c.img(c.catalog.hero.visual.head)}${c.img(art.frame,'ref-item-frame')}</div><strong class="${h.level>=cost.minLevel?'enough':'missing'}">${h.level}/${cost.minLevel}</strong></div></div>${button(c,'Thức tỉnh','upgrade','yellow',`data-type="star" data-submit ${max?'disabled':''}`)}</section>`;
}
// Trang bị đặc thù: dựng theo prefab PanelSpecialEquip và PopupSpecialEquipUpgrade (scene 1156, 1140).
const se={title:'fd4e2fd1f56341945bdbd2c235c9c2c1_2',content:'55ed8f9e77332724eb86da9c3ac4a974_2',head:'687c9876b626b414eba4d598804beb8c_2',arch:'04f378a587f28364fb31fa36f8b052cb_2',paper:'07cf5c66ca4802f45b38211ec4bcd2c7_2',mask:'4246161c1784bf14b8c1503cbd93fd20_2',ring:'7a3627ffee4eb134f92ad683ad85325d_2',bar:'77459f0b64ff0494eb6c84f23483a66d_2',line:'e3cf2d7e7e2d3a444beebc14e7430db8_2',lock:'e292c3306bbdb5d44a318ef7a5a57b9a_2',dot:'dfed522853d91b64780ea3fd5654cbd7_2',
 stars:['cebd03a36adae704aace75b84c8bac45_2','6ff5c2ac3f42c3f458d0158c7fbe595c_2','808395e8310fdca4cb53f7b63c77767c_2'],popupBg:'be0a4af988b6c514780ef7752174fd8d_2',frame:'1df7ea25bb6aad64985dc7d1ff9c508e_2',rightBg:'fbc43d986cb36ab439db19dc5d1d8eb1_2',rightTitle:'9d055745cf87c7c44abf0b0a8c61b62e_2',tabOn:'2b01ebfe025ad634f83cdc9057793ba6_2',tabOff:'39b69f3c5ad4b1d478b8553b5876585a_2',close:'323b29808cb00844a8401584624604b2_2',arrow:'8a8a49aeea124174994c02e6cb1d2f2f_2',field:'4273659df77514546beae6884ba2ae28_2',gold:'cc22864ccf28a2a479f402db5064938d_2',stone:'01b2ae54c918ffa4fb49b40596fddce9_2'};
const statName={attack:'Công',maxHp:'Máu'},resourceIds=['consumable:2028','consumable:2144'];
const have=(c,id)=>id==='gold'?c.player.wallet.gold:c.player.inventory[id]||0;
const affordable=(c,cost)=>!!cost&&have(c,'gold')>=cost.gold&&Object.entries(cost.items).every(([id,n])=>have(c,id)>=n);
/** Chấm đỏ ImageNotify: nâng được cấp hoặc phẩm ngay. */
function specialReady(c,s){return !s.locked&&(!s.levelBlock&&affordable(c,s.levelCost)||!s.tierBlock&&affordable(c,s.tierCost))}
/** GroupAllStar: phẩm 1-5 sao vàng, 6-10 sao tím, 11-15 sao đỏ; mỗi dải hiện số sao trong dải đó. */
function specialStars(c,tier){const band=tier<=5?0:tier<=10?1:2,count=tier-band*5;return `<span class="se-stars" style="background-image:url('${c.assetSrc(se.bar)}')">${Array.from({length:count},()=>c.img(se.stars[band],'se-star band'+band)).join('')}</span>`}
function specialBadge(c,s){const item=c.itemMap.get(s.icon);return `<span class="se-badge">${c.img(se.mask,'se-badge-bg')}${c.img(item?.assetKey,'se-badge-icon',item?.name)}${c.img(se.ring,'se-badge-ring')}</span>`}
function specialColumn(c,s,heading,action,selected){
 const stat=statName[s.stat];
 return `<article class="se-side ${s.locked?'locked':''} ${selected?'selected':''}"><h3 style="background-image:url('${c.assetSrc(se.head)}')">${heading}</h3>${c.img(se.paper,'se-paper')}${c.img(se.arch,'se-arch')}<button class="se-medal" data-action="${action}" data-slot="${s.key}" aria-label="${c.escape(s.label)}" ${s.locked?`title="${c.escape(s.lock)}"`:''}>${specialBadge(c,s)}${s.locked?c.img(se.lock,'se-lock'):''}</button>${!s.locked&&specialReady(c,s)?c.img(se.dot,'se-dot'):''}${s.locked?'':specialStars(c,s.tier)}<h4 style="background-image:url('${c.assetSrc(se.line)}')">${c.escape(s.label)}</h4><p class="se-level" style="background-image:url('${c.assetSrc(se.bar)}')">Cấp độ: ${s.level}</p><div class="se-stats">${s.locked?`<p class="se-locked-text">${c.escape(s.lock)}</p>`:`<p>${stat}: +${c.num(s.flat)}</p><p>${stat}: +${s.percent}%</p>`}</div></article>`;
}
function specialContent(c,sp,action,selected){return `<div class="se-content">${specialColumn(c,sp.role,I2('LBL_ROLE','Vai trò'),action,selected==='role')}${specialColumn(c,sp.rank,'Nhóm hạng',action,selected==='rank')}</div>`}
function special(c){const sp=c.player.hero.special;if(!sp?.role)return `<section class="reference-special"><h2 class="se-title" style="background-image:url('${c.assetSrc(se.title)}')">Trang bị đặc thù</h2><p class="se-offline">Máy chủ chưa có dữ liệu Trang bị đặc thù. Hãy khởi động lại server (npm start).</p></section>`;return `<section class="reference-special" style="--content:url('${c.assetSrc(se.content)}')"><h2 class="se-title" style="background-image:url('${c.assetSrc(se.title)}')">Trang bị đặc thù</h2>${specialContent(c,sp,'se-open')}</section>`}
function seField(c,id,need){const icon=id==='gold'?se.gold:id==='consumable:2028'?se.stone:c.itemMap.get(id)?.assetKey,owned=have(c,id);return `<span class="se-field ${need!==undefined&&owned<need?'lack':''}" style="background-image:url('${c.assetSrc(se.field)}')" title="${c.escape(id==='gold'?'Vàng':c.itemMap.get(id)?.name||id)}">${c.img(icon)}<b>${need===undefined?c.short(owned):c.short(owned)+'/'+c.short(need)}</b></span>`}
function seFee(c,cost){return `<div class="se-fee">${['gold',...resourceIds.filter(id=>cost.items[id])].map(id=>seField(c,id,id==='gold'?cost.gold:cost.items[id])).join('')}</div>`}
function seItems(c,cost){return `<div class="se-items">${Object.keys(cost.items).filter(id=>!resourceIds.includes(id)).map(id=>{const item=c.itemMap.get(id);return item?`<div class="se-item">${tile(c,item,null,'se-item')}<b class="${have(c,id)>=cost.items[id]?'enough':'missing'}">${c.short(have(c,id))}/${c.short(cost.items[id])}</b></div>`:''}).join('')}</div>`}
function seIcon(c,s,tier){return `<div class="se-big">${specialBadge(c,s)}${specialStars(c,tier)}</div>`}
/** PopupSpecialEquipUpgrade: bên trái chọn món, bên phải tab Cường hóa (cấp) và Phẩm đồ (phẩm). */
function specialPopup(c,state){
 const sp=c.player.hero.special,s=sp[state.slot],stat=statName[s.stat],strengthen=state.tab!=='tier';
 const tabs=[['level','Cường hóa',!s.levelBlock&&affordable(c,s.levelCost)],['tier',I2('LBL_COORDINATION','Phẩm đồ'),!s.tierBlock&&affordable(c,s.tierCost)]].map(([id,label,ready])=>{const on=(id==='tier')!==strengthen;return `<button class="se-tab ${on?'selected':''}" data-action="se-tab" data-tab="${id}" style="background-image:url('${c.assetSrc(on?se.tabOn:se.tabOff)}')">${label}${ready?c.img(se.dot,'se-tab-dot'):''}</button>`}).join('');
 let body;
 if(strengthen){
  const max=s.level>=sp.maxLevel;
  body=`<div class="se-panel se-strengthen">${seIcon(c,s,s.tier)}${max?`<p class="se-max">Đã đạt cấp độ tối đa</p>`:`<div class="se-compare"><span>${stat} +${c.num(s.flat)}<small>Cấp ${s.level}</small></span>${c.img(se.arrow,'se-arrow')}<span class="next">${stat} +${c.num(s.nextFlat)}<small>Cấp ${s.level+1}</small></span></div>`}</div>${max?'':`<p class="se-need">Nguyên liệu cần dùng</p>${seFee(c,s.levelCost)}`}${s.levelBlock&&!max?`<p class="se-block">${c.escape(s.levelBlock)}</p>`:''}${button(c,'Nâng cấp','se-upgrade','green',`data-slot="${s.key}" data-kind="level" data-submit ${s.levelBlock?'disabled':''}`)}`;
 }else{
  const max=s.tier>=sp.maxTier;
  body=`<div class="se-panel se-coordination"><div>${seIcon(c,s,s.tier)}<p>${stat} +${s.percent}%</p></div>${max?'':`<span class="se-arrows">${c.img(se.arrow,'se-arrow')}${c.img(se.arrow,'se-arrow')}</span><div>${seIcon(c,s,s.tier+1)}<p class="next">${stat} +${s.nextPercent}%</p></div>`}</div>${max?`<p class="se-max">Phẩm đồ đạt tối đa</p>`:`<p class="se-need">Nguyên liệu cần dùng</p>${seItems(c,s.tierCost)}${seFee(c,s.tierCost)}`}${s.tierBlock&&!max?`<p class="se-block">${c.escape(s.tierBlock)}</p>`:''}${button(c,'Nâng phẩm','se-upgrade','green',`data-slot="${s.key}" data-kind="tier" data-submit ${s.tierBlock?'disabled':''}`)}`;
 }
 return `<div class="special-popup" role="dialog" aria-modal="true" aria-label="Nâng cấp trang bị đặc thù" style="background-image:url('${c.assetSrc(se.popupBg)}');--content:url('${c.assetSrc(se.content)}')"><div class="se-assets">${seField(c,'gold')}${seField(c,'consumable:2028')}${s.level>=250?seField(c,'consumable:2144'):''}</div><section class="se-left" style="--frame:url('${c.assetSrc(se.frame)}')">${specialContent(c,sp,'se-slot',state.slot)}</section><nav class="se-tabs">${tabs}</nav><button class="se-close" data-action="se-close" aria-label="Đóng">${c.img(se.close)}</button><section class="se-right" style="--frame:url('${c.assetSrc(se.rightBg)}')"><h2 style="background-image:url('${c.assetSrc(se.rightTitle)}')">${strengthen?'Nâng cấp':'Nâng phẩm'}</h2>${body}</section></div>`;
}
function inventory(c){
 const groups=[['equipment','Trang bị','d099ea3ea8dd57743b56fad45a1b7a26_2','ee164ca05f66332489da1182d95a6d91_2'],['consumable','Vật phẩm','720817b81119e5a44a0cd4e69a8b2cc7_2','2c58206ba5276884aa4a2c4af442ea20_2'],['shard','Mảnh','e002366e2c063c649a2e717f12db839c_2','652141ac7b1e8a64aa3cac960a4626e0_2'],['artifact',I2('LBL_ARTIFACT','Bảo vật'),'93fb2e75e7fadb24dbf841d958627abe_2','fc34043e5001bbb48a372f9f67b80151_2']];
 const group=['all','material'].includes(c.inventoryTab)?'consumable':c.inventoryTab;
 // Bảo vật đã nâng cấp là khóa biến thể "artifact:<id>@<sao>:<exp>", không có trong catalog: thêm từ túi đồ.
 const variants=c.dictionary?[]:Object.keys(c.player.inventory).filter(k=>k.includes('@')&&c.player.inventory[k]>0).map(k=>c.itemMap.get(k)).filter(Boolean);
 const list=[...c.catalog.items,...variants].filter(item=>(c.dictionary||c.player.inventory[item.id]>0)&&(item.category===group||group==='consumable'&&item.category==='material')&&item.name.toLocaleLowerCase('vi').includes(c.search.toLocaleLowerCase('vi')));
 return `<section class="reference-inventory" aria-label="Túi đồ" style="--panel-image:url('${c.assetSrc(art.body)}')"><h2 class="reference-title">Túi đồ</h2><div class="reference-bag-list inventory-grid">${list.map(item=>tile(c,item,c.player.inventory[item.id]||0)).join('')}${list.length?'':'<p class="bag-empty">Chưa có vật phẩm.</p>'}</div><nav class="reference-bag-tabs" aria-label="Loại vật phẩm">${groups.map(([id,label,on,off])=>`<button data-action="inventory-tab" data-tab="${id}" data-shop="false" class="${group===id?'selected':''}" aria-label="${label}" title="${label}">${c.img(group===id?on:off)}</button>`).join('')}</nav><button class="bag-back" data-action="home" aria-label="Trở về">${c.img(c.named('button_back'))}</button><button class="bag-heroes" data-action="hero" aria-label="Tướng">${c.img(c.named('home2_hero'))}<span>Tướng</span></button><details class="bag-tools"><summary aria-label="Tìm kiếm và từ điển">⌕</summary><input id="item-search" aria-label="Tìm vật phẩm" placeholder="Tìm vật phẩm…" value="${c.escape(c.search)}"><button data-action="dictionary">${c.dictionary?'Về túi đồ':'Từ điển vật phẩm'}</button></details></section>`;
}
function profile(c){
 const p=c.player,expMax=p.account.level*100;
 const content=`<div class="profile-box"><div class="profile-avatar">${c.img(c.catalog.hero.visual.head)}${c.img(c.named('border_avatar'),'profile-avatar-border')}<span>${p.account.level}</span></div><div class="profile-name">${c.escape(p.displayName)}</div><div class="profile-details"><p>Tài khoản: ${c.escape(p.profile?.username||p.displayName)}</p><p title="${c.escape(p.profile?.id||'')}">ID: ${c.escape(p.profile?.id?.slice(-8)||'—')}</p><p>Hạm đội: _ _ _</p><p>Server: Máy chủ cục bộ</p></div><div class="profile-actions">${button(c,I2('LBL_EDIT','Sửa'),'profile-edit')}${button(c,I2('LBL_CHANGE_SERVER','Đổi Server'),'server-info','blue')}${button(c,'Đăng xuất','logout','red')}</div><div class="profile-exp">${c.img(c.named('icon_exp'))}<div><span style="width:${Math.min(100,p.account.exp/expMax*100)}%"></span><strong>${p.account.exp}/${expMax}</strong></div></div></div><div class="profile-sounds">${[['sound','Hiệu ứng','button_sound_'],['music','Nhạc nền','button_music_']].map(([id,label,name])=>`<div><label>${label}</label><button class="profile-sound" data-action="audio-toggle" data-audio="${id}" aria-label="${label}" aria-pressed="${c.audio[id]}">${c.img(c.named(name+(c.audio[id]?'on':'off')))}</button></div>`).join('')}</div><nav class="profile-side-tabs"><button aria-label="Thông tin" class="selected">${c.img(c.named('tab_account_on'))}</button><button data-action="journal" aria-label="Nhật ký">${c.img(c.named('edit_off'))}</button></nav>`;
 return overlay(c,'Thông tin',content,'reference-profile');
}
function mailTile(c,r){const wallet={gold:'icon_gold',diamonds:'icon_gem'}[r.itemId];if(wallet)return `<div class="ref-material-icon">${c.img(c.named(wallet))}${c.img(art.frame,'ref-item-frame')}<span class="ref-item-quantity">${c.short(r.quantity)}</span></div>`;const item=c.itemMap.get(r.itemId);return item?tile(c,item,r.quantity,'mail-reward'):''}
// Thư đã nhận: hộp quà xám, người gửi "Hệ thống" và giờ gửi (hôm nay: "10:57 SA", ngày khác: "08/11 10:57 SA").
const mailTime=at=>{if(!at)return'';const d=new Date(at),time=d.toLocaleTimeString('vi-VN',{hour:'2-digit',minute:'2-digit',hour12:true});return d.toDateString()===new Date().toDateString()?time:`${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')} ${time}`};
function mail(c){
 const claimed=true,deleted=c.deletedMail,selected=c.mailSelection,letters=c.player.mail||[],pending=letters.some(m=>!m.claimedAt);
 const mails=[...letters.map(m=>({id:'m:'+m.id,mailId:m.id,title:c.escape(m.title),text:c.escape(m.text),rewards:m.rewards,claimed:!!m.claimedAt,sentAt:m.sentAt})),...(!deleted.includes('journey')?[{id:'journey',title:'Hải trình',text:'Chào mừng thuyền trưởng! Hãy cùng Luffy khám phá các màn chơi và nhận phần thưởng chiến thắng.'}]:[])];
 const current=mails.find(m=>m.id===selected)||mails[0],daily=current?.id==='daily';
 const reward=daily?`<div class="mail-rewards">${[ ['icon_gold',c.catalog.economy.dailyGold],['icon_gem',c.catalog.economy.dailyDiamonds] ].map(([name,qty])=>`<div class="ref-material-icon">${c.img(c.named(name))}${c.img(art.frame,'ref-item-frame')}<span class="ref-item-quantity">${c.short(qty)}</span></div>`).join('')}${tile(c,c.itemMap.get('material:training'),2,'mail-reward')}${claimed?c.img(c.named('tag_received'),'mail-received'):''}</div>`:current?.mailId?`<div class="mail-rewards">${current.rewards.map(r=>mailTile(c,r)).join('')}${current.claimed?c.img(c.named('tag_received'),'mail-received'):''}</div>`:'';
 return overlay(c,I2('LBL_HOME_2_SCENE_TITILE_MAIL','Hòm thư'),`<div class="mail-left"><div class="mail-list">${mails.map(m=>`<button class="mail-row ${current.id===m.id?'selected':''}" data-action="mail-select" data-mail="${m.id}">${m.claimed?`${c.img(c.named('icon_mail_gift'),'mail-gift-read')}<strong>Hệ thống</strong><span class="mail-time">${mailTime(m.sentAt)}</span>`:`${c.img(c.named('icon_mail_gift'))}<strong>${m.title}</strong><span>${m.mailId?'Có quà':m.id==='daily'?(claimed?'Đã nhận':'Hôm nay'):'Hệ thống'}</span>`}</button>`).join('')}</div><div class="mail-left-actions">${button(c,'Nhận nhanh','mail-claim-all','yellow',claimed&&!pending?'disabled':'data-submit')}${button(c,c.img(c.named('trash_bin')),'mail-delete-all','red',`aria-label="Xóa thư đã đọc"`)}</div></div><div class="mail-right">${current?`<h3>${daily?'Phần thưởng điểm danh':current.title}</h3><p>${current.text}</p>${reward}<div class="mail-right-actions">${current.mailId&&!current.claimed?button(c,'Nhận','mail-open','green',`data-mail="${current.mailId}" data-submit`):daily&&!claimed?button(c,'Nhận','mail-claim','green','data-submit'):button(c,I2('LBL_DELETE','Xóa'),'mail-delete','yellow',`data-mail="${current.id}"`)}</div>`:'<p class="mail-empty">Hòm thư trống.</p>'}</div>`,'reference-mail');
}
function combatSkills(c){return `<div class="battle-skill-summary"><p>Chiến đấu theo lượt. Nhân vật tự chọn chiêu.</p>${c.catalog.skills.map(skill=>`<div title="${c.escape(c.player.hero.skillDetails?.[skill.id]?.description||skill.description)}">${c.img(skill.assetKey)}<span>${c.escape(skill.name)}<small>Cấp ${c.player.hero.skills[skill.id]} · ${skill.passive?'Bị động':'Tự dùng khi đủ '+skill.energy+' nộ'+(skill.cooldown?' và hết hồi chiêu':'')}</small></span></div>`).join('')}</div>`}
// Nhiệm vụ hằng ngày: PopupDailyQuest (scene 1288) và CellDailyQuest (scene 1163).
const dq={cell:'1eda22b640d5e134eaaaa8d9106e6dee_2',scroll:'9b56195f12b03c44db993d62800c7dd7_2',barBg:'c6c135dfe436dda4b8bd62a55502fc99_2',barFill:'b8a1c851646e9f94890d5fc09a8aed83_2',tick:'bba745a01cbc4064297dc55cc48349fb_2'};
const dqClock=s=>[Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':');
function dqReward(c,r){const wallet={gold:'icon_gold',diamonds:'icon_gem',spirit:'icon_spirit'}[r.itemId];if(wallet)return `<div class="ref-material-icon" title="${({gold:'Vàng',diamonds:'Kim cương',spirit:'EXP tướng'})[r.itemId]}">${c.img(c.named(wallet))}${c.img(art.frame,'ref-item-frame')}<span class="ref-item-quantity">${c.short(r.quantity)}</span></div>`;const item=c.itemMap.get(r.itemId);return item?tile(c,item,r.quantity,'dq-item'):''}
function dqCell(c,q,{final=false}={}){
 const progress=Math.min(q.progress,q.target),ready=!q.claimed&&progress>=q.target,pct=Math.round(progress/q.target*100);
 const action=q.claimed?c.img(dq.tick,'dq-check',''):ready?button(c,'Nhận','dq-claim','red',`data-quest="${final?'final':q.id}" data-submit`):final?'':button(c,'Thực hiện','dq-go','red',`data-go="${q.go}"`);
 return `<article class="dq-cell ${final?'final':''} ${q.claimed?'claimed':''}"><h3>${c.escape(q.name)}</h3><div class="dq-bar" style="--bg:url('${c.assetSrc(dq.barBg)}');--fill:url('${c.assetSrc(dq.barFill)}')"><span style="width:${pct}%"></span><b>${progress}/${q.target}</b></div><div class="dq-rewards">${q.rewards.map(r=>dqReward(c,r)).join('')}</div><div class="dq-action">${action}</div></article>`;
}
function dailyQuest(c){
 const d=c.player.dailyQuest;if(!d)return overlay(c,I2('LBL_MISSION','Nhiệm vụ'),'<p class="dq-offline">Máy chủ chưa có dữ liệu Nhiệm vụ. Hãy khởi động lại server (npm start).</p>','reference-daily');
 const list=[...d.quests].sort((a,b)=>(a.claimed-b.claimed)||((b.progress>=b.target)-(a.progress>=a.target)));
 return overlay(c,I2('LBL_MISSION','Nhiệm vụ'),`<p class="dq-refresh">Làm mới sau: <b class="dq-countdown" data-reset="${d.resetIn}">${dqClock(d.resetIn)}</b></p><div class="dq-summary" style="--cell:url('${c.assetSrc(dq.cell)}')">${dqCell(c,d.final,{final:true})}</div><div class="dq-scroll" style="--scroll:url('${c.assetSrc(dq.scroll)}');--cell:url('${c.assetSrc(dq.cell)}')">${list.map(q=>dqCell(c,q)).join('')}</div>`,'reference-daily');
}
window.ReferenceUI={dailyQuest,art,button,tile,overlay,equipment,awakening,special,specialPopup,specialReady,inventory,profile,mail,combatSkills};
})();
